%% step_1_source_2_find_missing.m
% Check for Missing EEG and Sidecar Files
% This script loads the EEG file list generated by script_1.m,
% checks whether each listed EEG file and its associated sidecar files exist,
% and adds new columns to flag missing files. The updated table overwrites the original file.

log_command_window('start');
clear; clc;

%% Section 1: Setup

% Define base paths
local_base = '/Users/lukebaxter/pipeline_paper/simple-oxford';
file_list_name = 'dataset_list_prelim.xlsx';
file_list_path = fullfile(local_base, 'data_lists', file_list_name);

% Read the existing table
file_table = readtable(file_list_path, 'PreserveVariableNames', true);

% Define new columns to add
missing_cols = {...
    'EEGfile_missing', 'dap_missing', 'rs3_missing', 'ceo_missing', 'cef_missing', ...
    'cdt_dpa_missing', 'cdt_ceo_missing', 'cdt_cef_missing', ...
    'urevents_csv_missing', 'events_csv_missing'};

% Add new columns initialized with empty strings
for c = 1:length(missing_cols)
    file_table.(missing_cols{c}) = strings(height(file_table), 1);
end

%% Section 2: Loop through each row of the table
n_rows = height(file_table);

for i = 1:n_rows
    % Extract basic row info
    subjectID = file_table.subjectID(i);
    sessionID = file_table.sessionID(i);
    runID     = file_table.runID(i);
    row_label = subjectID + "_" + sessionID + "_" + runID;

    % Display progress to screen
    fprintf('Checking row %d of %d: %s\n', i, n_rows, row_label);

    % Extract path and format
    path_i = file_table.path(i);
    format_i = string(file_table.format{i});

    % Handle rows with missing EEGfile or format (likely missing session folder)
    if strlength(file_table.EEGfile(i)) == 0 || strlength(format_i) == 0
        for c = 1:length(missing_cols)
            file_table.(missing_cols{c})(i) = "missing";
        end
        continue;
    end

    % Always check the main EEG file
    eegfile = file_table.EEGfile(i);
    if ~isfile(fullfile(path_i, eegfile))
        file_table.EEGfile_missing(i) = "missing";
    end

    % Check sidecar files based on format
    switch format_i
        case "Curry 7"
            check_fields = {'dap', 'rs3', 'ceo', 'cef'};
        case "Curry 8"
            check_fields = {'cdt_dpa', 'cdt_ceo', 'cdt_cef'};
        case "XDF"
            check_fields = {'urevents_csv', 'events_csv'};
        otherwise
            check_fields = {};
    end

    for f = 1:length(check_fields)
        fname = file_table.(check_fields{f})(i);
        if strlength(fname) > 0 && ~isfile(fullfile(path_i, fname))
            file_table.([check_fields{f} '_missing'])(i) = "missing";
        end
    end
end

%% Section 3: Save updated table
writetable(file_table, file_list_path);

%% Section 4: Print summary
% Count how many rows have at least one "missing" entry in any *_missing column
missing_matrix = file_table{:, missing_cols} == "missing";  % Logical matrix
row_missing = any(missing_matrix, 2);  % True if any column is missing in that row
missing_row_count = sum(row_missing);  % Count rows with at least one missing file

fprintf('\nTotal rows with missing files: %d\n', missing_row_count);

fprintf('Updated table saved to: %s\n', file_list_path);

log_command_window('stop');
